const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={capital:100,loss:5,trades:3,leverage:3,symbol:'BTCUSDT',instruction:'가격·거래량·미결제약정을 함께 확인하고 진입 근거가 부족하면 관망한다.'};
let saved;try{saved=JSON.parse(localStorage.getItem('coinmate-v1'))}catch{}let state={page:'desk',config:{...defaults,...saved?.config},messages:saved?.messages||[],logs:saved?.logs||[],history:saved?.history||[],realized:saved?.realized||0,position:saved?.position||null,running:false,approved:false,step:0};
const nav=[['desk','◈','트레이딩 데스크'],['strategy','☷','전략 관리'],['history','↔','거래 기록'],['logs','≡','실행 로그'],['connections','⌁','연결 설정']];
const money=n=>Number(n).toFixed(2);const signed=n=>(n>=0?'+':'')+money(n);const tm=()=>new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});let toastTimer;
function persist(){localStorage.setItem('coinmate-v1',JSON.stringify({config:state.config,messages:state.messages.slice(-60),logs:state.logs.slice(-100),history:state.history,realized:state.realized,position:state.position}))}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function log(text){state.logs.unshift({time:tm(),text});persist()}const unreal=()=>state.position?(state.position.mark-state.position.entry)*state.position.qty:0;const total=()=>state.realized+unreal();
function render(){const page=nav.find(n=>n[0]===state.page);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#" data-page="desk"><span class="mark">⌁</span>coinmate<span style="color:var(--green)">.</span></a><div><div class="nav-label small">WORKSPACE</div><nav class="nav">${nav.map(n=>`<button data-page="${n[0]}" class="${state.page===n[0]?'active':''}"><span class="icon">${n[1]}</span>${n[2]}</button>`).join('')}</nav></div><div class="side-note"><span class="dot"></span>나만의 트레이딩 파트너<br>대화로 전략을 설계하고<br>정해진 원칙을 실행하세요.<br><span style="color:#bbc7ac">현재 브라우저 모의 환경</span></div><div class="profile"><div class="avatar">TW</div><div>개인 워크스페이스<div class="sub" style="font-size:10px">로컬 저장 · Demo v0.1</div></div></div></aside><main><header class="topbar"><div class="crumb"><button class="mobile-menu" aria-label="메뉴 열기">☰</button>워크스페이스 <span>/ &nbsp; ${page[2]}</span></div><div class="tools"><span class="badge">◌ &nbsp; DEMO MODE</span><button class="btn connection-link" data-page="connections">⌁ &nbsp; 연결 설정</button><button class="avatar" data-page="connections" aria-label="개인 워크스페이스 설정">TW</button></div></header><div class="heading"><div><div class="small" style="margin-bottom:9px">YOUR PERSONAL TRADING PARTNER</div><h1>${state.page==='desk'?'대화로 설계하고, 원칙으로 실행하세요.':page[2]}</h1><p class="sub">${state.page==='desk'?'전략 대화부터 계좌 확인까지, 하나의 데스크에서.':'실행에 필요한 정보를 한곳에서 관리하세요.'}</p></div><span class="sub">${new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric'})}</span></div>${state.page==='desk'?desk():state.page==='strategy'?strategy():state.page==='history'?history():state.page==='logs'?logs():connections()}<footer><span>COINMATE &nbsp; / &nbsp; 대화에 집중하는 트레이딩</span><span>예시 잔고 · 모의 체결 · AI / 거래소 미연결</span></footer></main></div>`;bind();if(state.page==='desk')scrollChat()}
function desk(){return `<div class="metrics"><div class="metric"><label>총 자산 <span>↗</span></label><div class="value count">${money(state.config.capital+total())} <small>USDT</small></div><p class="sub">시작 자산 ${money(state.config.capital)} USDT</p></div><div class="metric"><label>모의 누적 손익 <span>◴</span></label><div class="value positive count">${signed(total())} <small>USDT</small></div><p class="sub">수수료 포함 · ${signed(total()/state.config.capital*100)}%</p></div><div class="metric"><label>사용 중인 증거금 <span>▧</span></label><div class="value count">${money(state.position?state.position.entry*state.position.qty/state.config.leverage:0)} <small>USDT</small></div><p class="sub">격리 모의 · ${state.config.leverage}× 레버리지</p></div><div class="metric"><label>모의 완료 거래 <span>↔</span></label><div class="value count">${state.history.length} <small>/ ${state.config.trades} 회</small></div><p class="sub">새 세션에서 한도 초기화</p></div></div><div class="workspace"><section class="panel chat-panel"><div class="panel-head"><h2>◈ &nbsp; 전략 대화</h2><span class="chat-status"><span class="dot"></span>규칙 기반 데모 응답</span></div><div class="chat-messages"><div class="day">나의 트레이딩 워크스페이스</div><div class="message"><div class="ai-icon">✳</div><div><div class="name">Coinmate <span class="time">시작 안내</span></div><div class="bubble">안녕하세요. 오늘의 매매 원칙부터 정해볼까요?<br>이 데스크에서 전략을 정리하고, 모의 실행 과정을 확인할 수 있어요.<br><br>현재 AI와 거래소는 연결되지 않았어요. 아래 전략은 수정 가능한 데모 예시예요.</div><div class="strategy-card"><strong>↗ &nbsp; 현재 전략 · ${esc(state.config.symbol)}</strong><div class="strategy-tags"><span class="tag">격리 ${state.config.leverage}×</span><span class="tag">세션 손실 한도 ${state.config.loss} USDT</span><span class="tag">최대 ${state.config.trades}회</span></div></div></div></div>${state.messages.map(m=>m.role==='user'?`<div class="message user"><div class="bubble">${esc(m.text)}</div></div>`:`<div class="message"><div class="ai-icon">✳</div><div><div class="name">Coinmate <span class="time">${esc(m.time)}</span></div><div class="bubble">${esc(m.text)}</div></div></div>`).join('')}</div><form class="composer" id="chat-form"><div class="prompts"><button type="button" data-prompt="현재 전략을 정리해줘">현재 전략 정리</button><button type="button" data-prompt="계좌 상태를 알려줘">계좌 상태 확인</button><button type="button" data-prompt="리스크 한도를 확인해줘">리스크 점검</button></div><div class="input-box"><textarea id="chat-input" aria-label="전략 메시지" placeholder="어떤 전략으로 거래할지 이야기해보세요…" maxlength="2000"></textarea><div class="input-bottom"><span>✳ &nbsp; Demo assistant &nbsp; · &nbsp; Enter로 전송</span><button class="send" aria-label="메시지 전송">↑</button></div></div><div class="footnote">데모 응답은 시장을 분석하거나 실제 주문을 실행하지 않습니다.</div></form></section><aside class="right-column"><section class="panel"><div class="panel-head"><h2>운용안 승인 · 실행</h2><span class="badge">모의</span></div><div class="right-body"><div class="status-title"><div class="status-orb">${state.running?'Ⅱ':'◌'}</div><div><p style="font-size:13px">${state.running?'모의 실행 중':'실행 대기 중'}</p><p class="sub" style="font-size:10px">로컬 실행기 미연결</p></div></div><div class="rows"><div class="row"><span class="key">적용 전략</span><span>${esc(state.config.symbol)} 기본 전략</span></div><div class="row"><span class="key">실행 방식</span><span>단계별 시나리오</span></div><div class="row"><span class="key">거래소</span><span class="muted">Binance · 미연결</span></div></div><div class="divider"></div><p class="sub">데모 운용안 · 증거금 최대 ${money(state.config.capital*.2)} USDT / 명목금액 ${money(state.config.capital*.2*state.config.leverage)} USDT / 최대 ${state.config.leverage}배 / 손실 한도 ${state.config.loss} USDT</p><button class="btn wide" id="approve-plan">${state.approved?"✓ 이 세션 운용안 승인됨":"운용안 검토 및 승인"}</button><div class="row"><span class="key">손실 한도 사용</span><span>${money(Math.max(0,-total()))} / ${state.config.loss}</span></div><div class="progress"><span style="width:${Math.min(100,Math.max(0,-total())/state.config.loss*100)}%"></span></div><p class="sub" style="font-size:10px">세션 누적 손실 한도 도달 시 신규 진입 중단</p><button class="btn ${state.running?'':'primary'} wide" id="toggle-run">${state.running?'Ⅱ 모의 실행 일시정지':'▷ 모의 실행 시작'}</button>${state.running?'<button class="btn wide" id="next-step">다음 시나리오 단계 →</button>':''}<button class="btn danger wide" id="emergency">□ &nbsp; 모의 긴급 중지 / 포지션 종료</button></div></section><section class="panel"><div class="panel-head"><h2>보유 포지션</h2><span class="sub">${state.position?'1':'0'}개</span></div><div class="right-body">${state.position?`<div class="row"><strong>${esc(state.position.symbol)}</strong><span class="positive">LONG · ${state.config.leverage}×</span></div><div class="divider"></div><div class="rows"><div class="row"><span class="key">진입가</span><span>${money(state.position.entry)}</span></div><div class="row"><span class="key">모의 현재가</span><span>${money(state.position.mark)}</span></div><div class="row"><span class="key">미실현 손익</span><span class="positive">${signed(unreal())} USDT</span></div></div><button class="btn wide" id="close-position">모의 포지션 종료</button>`:'<div class="empty"><div class="symbol">▧</div><p style="font-size:12px">현재 보유 중인 포지션이 없어요</p><p class="sub" style="font-size:10px;margin-top:7px">진입 시 근거와 손익이 여기에 표시됩니다.</p></div>'}<div class="activity"><span class="dot"></span>${esc(state.logs[0]?.text||'전략을 확인한 뒤 모의 실행을 시작하세요.')}</div></div></section></aside></div>`}
function strategy(){return `<div class="section"><div class="banner">전략 설정은 모의 시나리오에 적용됩니다. 채팅의 자유 입력은 메모로 보관되며, 아래 수치 설정을 자동으로 변경하지 않습니다.</div><form class="panel form-grid" id="strategy-form">${[['capital','모의 시작 자산 (USDT)',10,100000,.01],['loss','세션 누적 손실 한도 (USDT)',.01,100000,.01],['trades','세션 최대 완료 거래 수',1,100,1],['leverage','모의 레버리지',1,10,1]].map(([id,label,min,max,step])=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="number" min="${min}" max="${max}" step="${step}" required value="${state.config[id]}"></div>`).join('')}<div class="field"><label for="symbol">거래 대상</label><select name="symbol" id="symbol">${['BTCUSDT','ETHUSDT','SOLUSDT'].map(s=>`<option ${s===state.config.symbol?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>주문 모드</label><input disabled value="모의 전용 · 실거래 연결 필요"></div><div class="field full"><label for="instruction">전략 메모</label><textarea name="instruction" id="instruction" maxlength="3000">${esc(state.config.instruction)}</textarea></div><div class="full"><button class="btn primary">전략 저장</button><span class="sub" style="margin-left:12px">실행 중이거나 포지션 보유 중에는 변경할 수 없습니다.</span></div></form></div>`}
function history(){return `<div class="panel section"><div class="panel-head"><h2>모의 거래 기록</h2><button class="btn" id="export">CSV 내보내기</button></div><div class="table-wrap"><table><thead><tr><th>체결 시각</th><th>종목</th><th>방향</th><th>진입 / 종료</th><th>수수료 포함 손익</th></tr></thead><tbody>${state.history.length?state.history.map(h=>`<tr><td>${esc(h.time)}</td><td>${esc(h.symbol)}</td><td>LONG</td><td>${money(h.entry)} / ${money(h.exit)}</td><td style="color:${h.pnl>=0?'var(--positive)':'var(--red)'}">${signed(h.pnl)} USDT</td></tr>`).join(''):'<tr><td colspan="5" class="empty">아직 모의 거래 기록이 없습니다. 데스크에서 모의 실행을 시작하세요.</td></tr>'}</tbody></table></div></div>`}
function logs(){return `<div class="panel section"><div class="panel-head"><h2>실행 이벤트</h2><span class="sub">최근 100건</span></div>${state.logs.length?state.logs.slice(0,100).map(l=>`<div class="log-line"><time>${esc(l.time)}</time>${esc(l.text)}</div>`).join(''):'<div class="empty sub">아직 실행 이벤트가 없습니다.</div>'}</div>`}
function connections(){return `<div class="section"><div class="banner">현재 버전은 브라우저에 데이터를 저장하는 데모입니다. API 키를 입력받지 않습니다. Vercel 웹 화면 + PC 로컬 실행기 연결을 위한 구성입니다.</div><div class="panel connection"><h2>서비스 연결</h2>${[['✳','AI 모델','미연결','서버 API와 모델 키를 연결하면 실제 전략 대화가 활성화됩니다.'],['⌁','Binance Futures','미연결','계좌 조회와 주문은 로컬 실행기에서 거래소 API로 처리하도록 연결할 예정입니다.'],['▣','PC 로컬 실행기','오프라인','컴퓨터에서 실행되는 에이전트의 연결 상태와 heartbeat를 표시할 자리입니다.']].map(([icon,title,status,desc])=>`<div class="connection-card"><div><p style="margin-bottom:8px">${icon} &nbsp; ${title}</p><p class="sub">${desc}</p></div><span class="badge">${status}</span></div>`).join('')}<div class="divider"></div><h2>모의 세션 관리</h2><p class="sub" style="margin:12px 0">대화와 전략 설정은 유지하고 모의 잔고·거래·실행 로그를 초기화합니다.</p><button class="btn" id="reset">새 모의 세션 시작</button></div></div>`}
function reply(text){state.messages.push({role:'user',text,time:tm()});let answer;const c=state.config;if(/계좌|잔고|손익/.test(text))answer=`현재 모의 자산은 ${money(c.capital+total())} USDT, 누적 손익은 ${signed(total())} USDT입니다.\n보유 포지션: ${state.position?state.position.symbol+' LONG':'없음'}.\n실제 Binance 계좌는 연결되지 않았습니다.`;else if(/리스크|한도|손실/.test(text))answer=`현재 설정된 세션 손실 한도는 ${c.loss} USDT입니다. 완료 거래는 ${state.history.length}/${c.trades}회, 레버리지는 ${c.leverage}배입니다.\n이 값은 데모 예시이며 전략 관리에서 수정할 수 있습니다. 실거래의 손절 체결이나 손실액을 보장하는 기능은 아직 연결되지 않았습니다.`;else if(/전략|정리/.test(text))answer=`저장된 전략\n• 대상: ${c.symbol}, 격리 ${c.leverage}배\n• 세션 누적 손실 한도: ${c.loss} USDT\n• 최대 완료 거래: ${c.trades}회\n• 전략 메모: ${c.instruction}\n\n전략 관리 메뉴에서 수치를 변경하면 모의 실행에 적용됩니다.`;else answer='메모를 대화에 저장했어요.\n\n현재는 규칙 기반 데모 응답이므로 이 요청을 분석하거나 전략·주문에 자동 반영하지 않습니다. 전략 관리에서 실행 수치를 직접 저장할 수 있어요. 실제 AI 연결 후에는 대화 → 전략 초안 → 설정 검토 흐름으로 이어집니다.';state.messages.push({role:'assistant',text:answer,time:tm()});persist();render()}
function scrollChat(){const el=$('.chat-messages');if(el)el.scrollTop=el.scrollHeight}
function closePosition(reason){const p=state.position;if(!p)return;const fee=(p.entry+p.mark)*p.qty*.0005;const pnl=unreal()-fee;state.realized+=pnl;state.history.unshift({time:new Date().toLocaleString('ko-KR'),symbol:p.symbol,entry:p.entry,exit:p.mark,pnl});state.position=null;log(`${reason} · 수수료 포함 ${signed(pnl)} USDT`);if(state.history.length>=state.config.trades||total()<=-state.config.loss){state.running=false;log('세션 한도 도달 · 모의 실행 중단')}persist()}
function nextStep(){if(!state.running||!state.approved)return;if(!state.position){if(state.history.length>=state.config.trades||total()<=-state.config.loss){state.running=false;log('신규 진입 차단: 세션 한도 도달');render();return}const entry={BTCUSDT:60000,ETHUSDT:3000,SOLUSDT:150}[state.config.symbol];state.position={symbol:state.config.symbol,entry,mark:entry,qty:state.config.capital*.2*state.config.leverage/entry};state.step=1;log(`${state.config.symbol} 모의 LONG 진입 · 고정 시나리오 예시 가격`)}else if(state.step===1){state.position.mark=state.position.entry*1.003;state.step=2;log('모의 시나리오: 진입가 대비 +0.30% 이동')}else{closePosition('모의 시나리오 포지션 종료');state.step=0}persist();render()}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=e=>{e.preventDefault();state.page=b.dataset.page;render()});$('.mobile-menu').onclick=()=>$('.shell').classList.toggle('menu-open');const form=$('#chat-form');if(form){form.onsubmit=e=>{e.preventDefault();const t=$('#chat-input').value.trim();if(t)reply(t)};$('#chat-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();form.requestSubmit()}};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>reply(b.dataset.prompt));$('#approve-plan').onclick=()=>{if(state.running||state.position){toast('실행을 중지하고 포지션을 종료한 뒤 검토하세요.');return}if(confirm('모의 세션 운용안을 승인할까요?\n종목 '+state.config.symbol+' / 레버리지 '+state.config.leverage+'배\n최대 증거금 '+money(state.config.capital*.2)+' USDT\n최대 명목금액 '+money(state.config.capital*.2*state.config.leverage)+' USDT\n세션 손실 한도 '+state.config.loss+' USDT\n실제 주문은 실행되지 않습니다.')){state.approved=true;log('사용자 모의 운용안 승인');render()}};$('#toggle-run').onclick=()=>{if(!state.approved){toast('운용안을 먼저 검토하고 승인하세요.');return}if(!state.running&&(state.history.length>=state.config.trades||total()<=-state.config.loss)){toast('세션 한도에 도달했습니다. 새 모의 세션을 시작하세요.');return}state.running=!state.running;log(state.running?'모의 실행 시작 · 다음 단계 버튼으로 고정 시나리오 진행':'모의 실행 일시정지 · 보유 포지션 유지');render()};$('#emergency').onclick=()=>{state.running=false;state.approved=false;closePosition('모의 긴급 중지');log('모의 실행 중지 · 신규 진입 차단');render();toast('모의 실행을 중지하고 포지션을 종료했습니다.')};if($('#next-step'))$('#next-step').onclick=nextStep;if($('#close-position'))$('#close-position').onclick=()=>{closePosition('사용자 모의 청산');state.step=0;render()}}
if($('#strategy-form'))$('#strategy-form').onsubmit=e=>{e.preventDefault();if(state.running||state.position){toast('실행을 중지하고 포지션을 종료한 뒤 변경하세요.');return}const data=Object.fromEntries(new FormData(e.target));['capital','loss','trades','leverage'].forEach(k=>data[k]=Number(data[k]));if(data.loss>data.capital){toast('손실 한도는 시작 자산 이내로 설정하세요.');return}if(state.history.length&&data.capital!==state.config.capital){toast('시작 자산은 새 모의 세션에서 변경하세요.');return}state.config=data;state.approved=false;log('모의 전략 설정 저장');persist();render();toast('전략을 저장했습니다.')};if($('#reset'))$('#reset').onclick=()=>{if(!confirm('모의 거래·손익·실행 로그를 초기화할까요?'))return;Object.assign(state,{running:false,approved:false,position:null,history:[],realized:0,logs:[],step:0});log('새 모의 세션 시작');render();toast('모의 세션을 초기화했습니다.')};if($('#export'))$('#export').onclick=()=>{const csv='\ufeff시각,종목,방향,진입가,종료가,순손익(USDT)\n'+state.history.map(h=>[h.time,h.symbol,'LONG',h.entry,h.exit,h.pnl].map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='coinmate-demo-trades.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
render();
